filter.template:
{%- set ma = integration_entities('magic_areas') -%}
{%- set ex = config.get('exclude', []) -%}
{%- set word = {'motion': 'Motion', 'occupancy': 'Motion', 'moisture': 'Leak', 'door': 'Door', 'window': 'Window', 'opening': 'Opening', 'garage_door': 'Garage door', 'smoke': 'Smoke', 'gas': 'Gas', 'carbon_monoxide': 'CO', 'safety': 'Safety', 'tamper': 'Tamper', 'vibration': 'Vibration'} -%}
{%- set ns = namespace(l=[]) -%}
{%- for s in states.binary_sensor | selectattr('attributes.device_class','defined') | selectattr('attributes.device_class','in', word.keys() | list) -%}
{%- if s.entity_id not in ex and s.entity_id not in ma and area_id(s.entity_id) and not is_hidden_entity(s.entity_id) -%}
{%- set dev = device_id(s.entity_id) -%}
{%- set dn = (device_attr(dev, 'name_by_user') or device_attr(dev, 'name') or '') if dev else '' -%}
{%- set ns.l = ns.l + [{'entity': s.entity_id, 'area': area_name(s.entity_id), 'dev': dn, 'name': s.name, 'w': word[s.attributes.device_class], 'evo': s.entity_id.startswith('binary_sensor.evo192_zone_')}] -%}
{%- endif -%}
{%- endfor -%}
{%- set out = namespace(l=[]) -%}
{%- for area in ns.l | map(attribute='area') | unique | sort -%}
{%- set items = ns.l | selectattr('area', 'eq', area) | list -%}
{%- set strip = '(?i)(' ~ area ~ '|' ~ area | replace(' ', '') ~ '|zone|open|presence|occupancy|moisture|water|motion)' -%}
{%- set evos = items | selectattr('evo') | list | count -%}
{%- set tiles = namespace(l=[]) -%}
{%- for c in items -%}
{%- if c.evo -%}
{%- set raw = c.dev | regex_replace(strip, '') if evos > 1 else '' -%}
{%- set fallback = 'Alarm zone' -%}
{%- elif items | selectattr('w', 'eq', c.w) | list | count > 1 -%}
{%- set raw = (c.name | replace(c.dev, '')) if (items | selectattr('dev', 'eq', c.dev) | list | count) > 1 else c.dev -%}
{%- set raw = raw | regex_replace(strip, '') -%}
{%- set fallback = c.w -%}
{%- else -%}
{%- set raw = '' -%}
{%- set fallback = c.w -%}
{%- endif -%}
{%- set n = raw | regex_replace('\\s+', ' ') | trim -%}
{%- set n = 'Whole room' if n | lower == 'area' else n -%}
{%- set n = (n[:1] | upper ~ n[1:]) if n else fallback -%}
{%- set tiles.l = tiles.l + [{'type': 'custom:button-card', 'template': 'vg_stat', 'entity': c.entity, 'name': n}] -%}
{%- endfor -%}
{%- set out.l = out.l + [{'type': 'heading', 'heading': area, 'heading_style': 'subtitle'}, {'type': 'grid', 'columns': 2, 'square': false, 'cards': tiles.l | sort(attribute='name')}] -%}
{%- endfor -%}
{{ out.l }}

{%- set ns = namespace(l=[]) -%}
{%- for p in states.person | sort(attribute='name') -%}
{%- set ns.l = ns.l + [{'type': 'custom:button-card', 'template': 'vg_stat', 'entity': p.entity_id, 'name': p.name.split(' ') | first}] -%}
{%- endfor -%}
{{ ns.l }}

{%- set ex = config.get('exclude', []) -%}
{%- set ns = namespace(l=[]) -%}
{%- for s in states.camera | sort(attribute='entity_id') -%}
{%- if s.entity_id not in ex and area_id(s.entity_id) and not is_hidden_entity(s.entity_id) -%}
{%- set dev = device_id(s.entity_id) -%}
{%- set dn = (device_attr(dev, 'name_by_user') or device_attr(dev, 'name')) if dev else none -%}
{%- set ns.l = ns.l + [{'type': 'picture-entity', 'entity': s.entity_id, 'name': dn or area_name(s.entity_id), 'camera_view': 'auto', 'show_state': false, 'fit_mode': 'contain', 'tap_action': {'action': 'more-info'}, 'grid_options': {'columns': 'full', 'rows': 5}}] -%}
{%- endif -%}
{%- endfor -%}
{{ ns.l | sort(attribute='name') }}
